import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar
  },
  props: {
    formInfo: Object,
    flowSteps: Array,
    currentWeebhookData: Object
  },
  data() {
    return {
      SnackBarComponent: {},
      invokeUrl: "",
      webhoolAuth: ""
    };
  },
  created() {
    if (Object.keys(this.currentWeebhookData).length != 0) {
      this.invokeUrl = this.currentWeebhookData.invoke_url == "N/A" ? "" : this.currentWeebhookData.invoke_url;
      this.webhoolAuth = this.currentWeebhookData.authorization == "N/A" ? "" : this.currentWeebhookData.authorization;
    }
  },
  methods: {
    next_option() {
      var data = {};
      data = {
        invoke_url: this.invokeUrl == "" ? "N/A" : this.invokeUrl,
        authorization: this.webhoolAuth == "" ? "N/A" : this.webhoolAuth
      };
      this.$emit("webhookInfo", data);
    },
    back_step() {
      this.$emit("configStep", this.flowSteps);
    }
  }
};
